export type CallToolData = {
    body: ToolCall;
    headers?: {
        /**
         * An https:// URL to POST the outcome to, for a platform that cannot poll (for example Zapier `z.generateCallbackUrl()`). When the call queued a job, Hermoso POSTs the job resource — exactly what `GET /v1/jobs/{id}` answers — once the job is `done` or `error`, with headers `Hermoso-Event: job.done | job.error` and `Hermoso-Delivery` (also sent as `Idempotency-Key`; drop a repeat). A 2xx ends delivery; a 4xx other than 408, 425 and 429 is final; anything else is retried for about 16 hours. When the call finished inside the request, its response body is POSTed too (`Hermoso-Event: tool.result`). The response header `Hermoso-Callback` says what happened: `registered`, `sent`, `limit-reached` or `not-registered`. Nothing about what runs or what it costs changes: the URL is attached after the job is queued. A refusal is the HTTP error and nothing is POSTed. Must be https on a public host name; a replay with the same `Idempotency-Key` and a new URL adds that URL to the same job.
         */
        'X-Hermoso-Callback-Url'?: string;
        /**
         * Send a unique value to make this call safe to retry. A replay returns the original response with `Idempotency-Replayed: true`, for 24 hours — except a call that queued a job, whose replay is that job as it is now (what `GET /v1/jobs/{id}` answers), so a finished render replays as done with its file.
         */
        'Idempotency-Key'?: string;
        /**
         * Which profile to act on, when the account holds more than one: an `id` from `GET /v1/brands`. Defaults to the workspace the key is pinned to. Membership is re-authorised on every request, and an id this key cannot act on is a 404 `brand_not_found`, never an empty result.
         */
        'X-Hermoso-User'?: string;
    };
    path: {
        name: string;
    };
    query?: {
        /**
         * The same as the `X-Hermoso-Callback-Url` header, for a client that cannot set headers. Prefer the header: a callback URL is a secret, and query strings are logged. A callback implies `wait=0` unless you send `wait` yourself.
         */
        callback_url?: string;
        /**
         * How long to hold this request while a render finishes. Only tools that render through the job queue are affected: video, avatars, template ads, post-production, and image generation (`generate_image` is queued as an image job whenever `wait` is sent, including `wait=0`). Every other tool answers as it always does. OMIT IT and nothing changes: a render is held for up to 45 seconds and then answered 200 with `data.stillRendering: true` and a `data.jobId`. `wait=0` (or `false`) answers 202 with a job handle the moment the job is queued, which is what a platform with a 30-second step limit wants. `wait=<seconds>` holds at most that long, capped at 45, and answers 202 if the render is not finished by then. Not waiting never changes what a render costs or whether it runs: the job is queued, checked against your balance and billed exactly as it is when you wait. Poll `GET /v1/jobs/{id}`.
         */
        wait?: string;
    };
    url: '/v1/tools/{name}';
};

